/**
 * Pre-computed continent dot positions for globe visualization.
 * Generated by sampling points inside simplified continent polygons.
 * Each point is [lat, lng].
 */

// Point-in-polygon ray casting test
function pip(lat: number, lng: number, poly: [number, number][]): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [yi, xi] = poly[i];
    const [yj, xj] = poly[j];
    if ((yi > lng) !== (yj > lng) && lat < ((xj - xi) * (lng - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

