function sampleContinentDots(density: number): [number, number][] {
  const dots: [number, number][] = [];
  // Sample each polygon
  for (const poly of CONTINENT_POLYS) {
    // Find bounding box
    let minLat = 90, maxLat = -90, minLng = 180, maxLng = -180;
    for (const [lat, lng] of poly) {
      if (lat < minLat) minLat = lat;
      if (lat > maxLat) maxLat = lat;
      if (lng < minLng) minLng = lng;
      if (lng > maxLng) maxLng = lng;
    }
    // Sample within bounding box
    const step = density;
    for (let lat = minLat; lat <= maxLat; lat += step) {
      for (let lng = minLng; lng <= maxLng; lng += step) {
        if (pip(lat, lng, poly)) {
          // Add slight jitter for organic look
          const jLat = lat + (Math.random() - 0.5) * step * 0.4;
          const jLng = lng + (Math.random() - 0.5) * step * 0.4;
          dots.push([jLat, jLng]);
        }
      }
    }
  }
  return dots;
}

// Generate dots at ~2.5 degree spacing (~4000-5000 dots)
export const CONTINENT_DOTS: [number, number][] = sampleContinentDots(2.5);
